import { Link, useLocation } from 'react-router-dom';
import { Menu, X, Phone } from 'lucide-react';
import { useState } from 'react';

export default function Header() {
  const location = useLocation();
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  const navItems = [
    { href: '/', label: 'Home' },
    { href: '/services', label: 'Services' },
    { href: '/pricing', label: 'Pricing' },
    { href: '/about', label: 'About' },
    { href: '/contact', label: 'Contact' },
  ];

  return (
    <header className="sticky top-0 z-50 bg-background/95 backdrop-blur-sm border-b border-border shadow-sm">
      <div className="container mx-auto px-4">
        {/* Top bar */}
        <div className="hidden md:flex justify-end items-center py-1.5 border-b border-border/40 text-sm text-muted-foreground gap-2">
          <Phone size={13} className="text-primary" />
          <span>(555) 123-4567</span>
          <span className="mx-2 text-border">|</span>
          <span>Serving the Greater Metro Area</span>
        </div>

        <div className="flex h-20 items-center justify-between">
          <Link to="/" className="flex items-center shrink-0">
            <img
              src="/airo-assets/images/logo/horizontal"
              alt="Spotless Home Cleaning logo"
              className="h-12 w-auto object-contain shrink-0"
            />
          </Link>

          <nav className="hidden md:flex items-center gap-7">
            {navItems.map((item) => (
              <Link
                key={item.href}
                to={item.href}
                className={`text-sm font-medium transition-colors duration-200 hover:text-primary ${
                  location.pathname === item.href
                    ? 'text-primary'
                    : 'text-foreground/70'
                }`}
              >
                {item.label}
              </Link>
            ))}
            <Link
              to="/contact"
              className="ml-2 bg-primary text-primary-foreground text-sm font-semibold px-5 py-2.5 rounded-full hover:bg-primary/90 transition-colors duration-200 shadow-sm"
            >
              Get a Quote
            </Link>
          </nav>

          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 hover:bg-muted rounded-md transition-colors"
            aria-label="Toggle menu"
          >
            {isMobileMenuOpen ? <X size={22} /> : <Menu size={22} />}
          </button>
        </div>

        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-border py-4">
            <nav className="flex flex-col gap-1">
              {navItems.map((item) => (
                <Link
                  key={item.href}
                  to={item.href}
                  className={`text-sm font-medium transition-colors hover:text-primary py-2.5 px-2 rounded-md ${
                    location.pathname === item.href
                      ? 'text-primary bg-muted'
                      : 'text-foreground/70'
                  }`}
                  onClick={() => setIsMobileMenuOpen(false)}
                >
                  {item.label}
                </Link>
              ))}
              <Link
                to="/contact"
                className="mt-3 bg-primary text-primary-foreground text-sm font-semibold px-5 py-3 rounded-full text-center hover:bg-primary/90 transition-colors duration-200"
                onClick={() => setIsMobileMenuOpen(false)}
              >
                Get a Quote
              </Link>
              <div className="flex items-center gap-2 mt-3 px-2 text-sm text-muted-foreground">
                <Phone size={13} className="text-primary" />
                <span>(555) 123-4567</span>
              </div>
            </nav>
          </div>
        )}
      </div>
    </header>
  );
}

